2	 * Webhook endpoint management and the bridge from `webhook.delivery_requested` to the delivery queue.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, subscribe, isEnabled, wouldExceedLimit
5	 */
6	import { createHmac } from "node:crypto";
7	import { wouldExceedLimit } from "@/config/plan-limits";
8	import { subscribe } from "@/lib/event-bus";
9	import { isEnabled } from "@/lib/feature-flags";
10	import { randomToken } from "@/lib/hash";
11	import { assertCan } from "@/lib/permissions";
12	import { assertOrgScope } from "@/lib/tenant";
13	import * as orgRepo from "@/server/repositories/organization-repository";
14	import * as webhookRepo from "@/server/repositories/webhook-repository";
15	import { requireFound, webhookResource } from "./_support";
16	import type {
17	  CreateWebhookInput,
18	  DeleteWebhookInput,
19	  UpdateWebhookInput,
20	} from "@/schemas/webhook";
21	import type { WebhookEndpointRow } from "@/server/db/schema/webhooks";
22	import type { OrgId } from "@/types/common";
23	import type { Unsubscribe } from "@/types/event";
24	import type { FlagContext } from "@/types/feature-flag";
25	import type { Actor } from "@/types/member";
26	
27	/** Length in bytes of a generated endpoint signing secret. */
28	const SECRET_BYTES = 32;
29	
30	export async function listWebhooks(
31	  actor: Actor,
32	  orgId: OrgId,
33	): Promise<readonly WebhookEndpointRow[]> {
34	  assertOrgScope(actor, orgId);
35	  assertCan(actor, "webhook:manage", webhookResource(orgId, null));
36	  return webhookRepo.listEndpoints(orgId);
37	}
38	
39	/**
40	 * Creating an endpoint is gated twice: the `webhooks` flag has to be on for
41	 * the org's plan, and the plan's endpoint count must have room. A secret is
42	 * minted here and never regenerated — rotating it means deleting the endpoint.
43	 */
44	export async function createWebhook(
45	  actor: Actor,
46	  input: CreateWebhookInput,
47	): Promise<WebhookEndpointRow> {
48	  assertOrgScope(actor, input.orgId);
49	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, null));
50	
51	  const org = requireFound(
52	    await orgRepo.findOrgById(input.orgId),
53	    "Organization",
54	    input.orgId,
55	  );
56	
57	  if (!isEnabled("webhooks", flagContextFor(actor, org.plan, org.settings.enabledFlagOverrides))) {
58	    throw new Error("Outgoing webhooks are not included in this plan");
59	  }
60	
61	  const used = await webhookRepo.countEndpoints(input.orgId);
62	  if (wouldExceedLimit(org.plan, "webhooks", used)) {
63	    throw new Error(`Plan ${org.plan} allows ${used} webhook endpoints`);
64	  }
65	
66	  return webhookRepo.insertEndpoint(input, randomToken(SECRET_BYTES));
67	}
68	
69	export async function updateWebhook(
70	  actor: Actor,
71	  input: UpdateWebhookInput,
72	): Promise<WebhookEndpointRow> {
73	  assertOrgScope(actor, input.orgId);
74	  assertCan(actor, "webhook:manage", webhookResource(input.orgId, input.webhookId));
75	  return webhookRepo.updateEndpoint(input);
76	}
77	
78	export async function deleteWebhook(
79	  actor: Actor,
